SELECT "t0"."line_id", CASE WHEN "t0"."_ttrp_a_n17_0" IS NULL THEN NULL ELSE COALESCE("t5"."_ttrp_n_n17_0", 0) END AS "days_open"
FROM (SELECT "t"."line_id", "t"."request_number", "t"."item", "t"."quantity", "t"."way", "t"."customer", "t"."customer_email", "t"."obligation_id", "t"."due", "t"."obligation_state", "p_f7cce9af"."recipe", "p_f7cce9af"."run", "p_f7cce9af"."entity", "p_f7cce9af"."key", "p_f7cce9af"."kind", "p_f7cce9af"."due" AS "due0", "p_f7cce9af"."state", "p_f7cce9af"."fulfilled_by", "p_f7cce9af"."fulfilled_at", "p_f7cce9af"."created_at", "p_f7cce9af"."created_at" AS "_ttrp_a_n17_0"
        FROM (SELECT "p_da15c438"."line_id", "p_da15c438"."request_number", "p_da15c438"."item", "p_da15c438"."quantity", "p_da15c438"."way", "p_da15c438"."customer0" AS "customer", "p_da15c438"."email" AS "customer_email", "p_7d39f2a5"."id" AS "obligation_id", "p_7d39f2a5"."due", "p_7d39f2a5"."state" AS "obligation_state"
                FROM "p_da15c438"
                    INNER JOIN "p_7d39f2a5" ON "p_7d39f2a5"."entity" = 'return_request_line' AND "p_7d39f2a5"."key" = CAST("p_da15c438"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a5"."kind" = 'inbound' AND "p_7d39f2a5"."state" IN ('open', 'overdue', 'reopened')) AS "t"
            INNER JOIN "p_f7cce9af" ON "t"."obligation_id" = "p_f7cce9af"."id") AS "t0"
    LEFT JOIN (SELECT "t3"."_ttrp_a_n17_0" AS "_ttrp_k_n17_0__ttrp_a_n17_0", COUNT("p_23e6f28a"."_ttrp_d_n17_0") AS "_ttrp_n_n17_0"
        FROM (SELECT "p_f7cce9af0"."created_at" AS "_ttrp_a_n17_0"
                FROM (SELECT "p_da15c4380"."line_id", "p_da15c4380"."request_number", "p_da15c4380"."item", "p_da15c4380"."quantity", "p_da15c4380"."way", "p_da15c4380"."customer0" AS "customer", "p_da15c4380"."email" AS "customer_email", "p_7d39f2a50"."id" AS "obligation_id", "p_7d39f2a50"."due", "p_7d39f2a50"."state" AS "obligation_state"
                        FROM "p_da15c438" AS "p_da15c4380"
                            INNER JOIN "p_7d39f2a5" AS "p_7d39f2a50" ON "p_7d39f2a50"."entity" = 'return_request_line' AND "p_7d39f2a50"."key" = CAST("p_da15c4380"."line_id" AS VARCHAR(65536)) AND "p_7d39f2a50"."kind" = 'inbound' AND "p_7d39f2a50"."state" IN ('open', 'overdue', 'reopened')) AS "t1"
                    INNER JOIN "p_f7cce9af" AS "p_f7cce9af0" ON "t1"."obligation_id" = "p_f7cce9af0"."id"
                GROUP BY "p_f7cce9af0"."created_at") AS "t3"
            INNER JOIN "p_23e6f28a" ON "t3"."_ttrp_a_n17_0" < "p_23e6f28a"."_ttrp_d_n17_0" AND "p_23e6f28a"."_ttrp_d_n17_0" <= :as_of
        GROUP BY "t3"."_ttrp_a_n17_0") AS "t5" ON "t0"."_ttrp_a_n17_0" = "t5"."_ttrp_k_n17_0__ttrp_a_n17_0"
